587			) : undefined;
588	
589			// Prefer the controller's fork handler over the session's deprecated fork handler.
590			const controllerForkHandler = this._getForkHandlerForScheme(sessionResource.scheme);
591			let result: vscode.ChatSessionItem;
592			if (controllerForkHandler) {
593				result = await controllerForkHandler(sessionResource, requestTurn, token);
594			} else {
595				const entry = this._extHostChatSessions.get(sessionResource);
596				const sessionForkHandler = entry?.sessionObj.session.forkHandler;
597				if (!sessionForkHandler) {
598					throw new Error(`No fork handler found for session ${sessionResource.toString()}`);
599				}
